#include <iostream>
#include <string>
using namespace std;

class Speaker {
public:
    virtual void speak() const = 0;
    virtual ~Speaker() {}
};

class Cat : public Speaker {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    void speak() const override {
        cout << name << "：喵～本喵吃了 " << fish << " 条" << endl;
    }
};

class Fish : public Speaker {
    string name;
    int fish;
public:
    Fish(string n, int f) : name(n), fish(f) {}
    void speak() const override {
        cout << name << "：咕噜咕噜～本喵吃了 " << fish << " 条" << endl;
    }
};

void rollCall(const Speaker& s) {
    cout << "点名：" << endl;
    s.speak();
}

int main() {
    int a = 0;
    int b = 0;
    cin >> a >> b;

    Cat cat("{catName}", a);
    Fish fish("{fishName}", b);

    rollCall(cat);
    rollCall(fish);
    return 0;
}
